class Produit extends DataClass implements Insertable<Produit> {
  final int id;
  final String reference;
  final String? codeBarre;
  final String designation;
  final String unite;
  final double prixAchatHT;
  final double prixVenteHT;
  final double tauxTVA;
  final double stockMinimum;
  final int? categorieId;
  final Uint8List? imageData;
  final bool actif;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int? createdByUserId;
  const Produit({
    required this.id,
    required this.reference,
    this.codeBarre,
    required this.designation,
    required this.unite,
    required this.prixAchatHT,
    required this.prixVenteHT,
    required this.tauxTVA,
    required this.stockMinimum,
    this.categorieId,
    this.imageData,
    required this.actif,
    required this.createdAt,
    required this.updatedAt,
    this.createdByUserId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['reference'] = Variable<String>(reference);
    if (!nullToAbsent || codeBarre != null) {
      map['code_barre'] = Variable<String>(codeBarre);
    }
    map['designation'] = Variable<String>(designation);
    map['unite'] = Variable<String>(unite);
    map['prix_achat_h_t'] = Variable<double>(prixAchatHT);
    map['prix_vente_h_t'] = Variable<double>(prixVenteHT);
    map['taux_t_v_a'] = Variable<double>(tauxTVA);
    map['stock_minimum'] = Variable<double>(stockMinimum);
    if (!nullToAbsent || categorieId != null) {
      map['categorie_id'] = Variable<int>(categorieId);
    }
    if (!nullToAbsent || imageData != null) {
      map['image_data'] = Variable<Uint8List>(imageData);
    }
    map['actif'] = Variable<bool>(actif);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdByUserId != null) {
      map['created_by_user_id'] = Variable<int>(createdByUserId);
    }
    return map;
  }

  ProduitsCompanion toCompanion(bool nullToAbsent) {
    return ProduitsCompanion(
      id: Value(id),
      reference: Value(reference),
      codeBarre: codeBarre == null && nullToAbsent
          ? const Value.absent()
          : Value(codeBarre),
      designation: Value(designation),
      unite: Value(unite),
      prixAchatHT: Value(prixAchatHT),
      prixVenteHT: Value(prixVenteHT),
      tauxTVA: Value(tauxTVA),
      stockMinimum: Value(stockMinimum),
      categorieId: categorieId == null && nullToAbsent
          ? const Value.absent()
          : Value(categorieId),
      imageData: imageData == null && nullToAbsent
          ? const Value.absent()
          : Value(imageData),
      actif: Value(actif),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      createdByUserId: createdByUserId == null && nullToAbsent
          ? const Value.absent()
          : Value(createdByUserId),
    );
  }

  factory Produit.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Produit(
      id: serializer.fromJson<int>(json['id']),
      reference: serializer.fromJson<String>(json['reference']),
      codeBarre: serializer.fromJson<String?>(json['codeBarre']),
      designation: serializer.fromJson<String>(json['designation']),
      unite: serializer.fromJson<String>(json['unite']),
      prixAchatHT: serializer.fromJson<double>(json['prixAchatHT']),
      prixVenteHT: serializer.fromJson<double>(json['prixVenteHT']),
      tauxTVA: serializer.fromJson<double>(json['tauxTVA']),
      stockMinimum: serializer.fromJson<double>(json['stockMinimum']),
      categorieId: serializer.fromJson<int?>(json['categorieId']),
      imageData: serializer.fromJson<Uint8List?>(json['imageData']),
      actif: serializer.fromJson<bool>(json['actif']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      createdByUserId: serializer.fromJson<int?>(json['createdByUserId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'reference': serializer.toJson<String>(reference),
      'codeBarre': serializer.toJson<String?>(codeBarre),
      'designation': serializer.toJson<String>(designation),
      'unite': serializer.toJson<String>(unite),
      'prixAchatHT': serializer.toJson<double>(prixAchatHT),
      'prixVenteHT': serializer.toJson<double>(prixVenteHT),
      'tauxTVA': serializer.toJson<double>(tauxTVA),
      'stockMinimum': serializer.toJson<double>(stockMinimum),
      'categorieId': serializer.toJson<int?>(categorieId),
      'imageData': serializer.toJson<Uint8List?>(imageData),
      'actif': serializer.toJson<bool>(actif),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'createdByUserId': serializer.toJson<int?>(createdByUserId),
    };
  }

  Produit copyWith({
    int? id,
    String? reference,
    Value<String?> codeBarre = const Value.absent(),
    String? designation,
    String? unite,
    double? prixAchatHT,
    double? prixVenteHT,
    double? tauxTVA,
    double? stockMinimum,
    Value<int?> categorieId = const Value.absent(),
    Value<Uint8List?> imageData = const Value.absent(),
    bool? actif,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<int?> createdByUserId = const Value.absent(),
  }) => Produit(
    id: id ?? this.id,
    reference: reference ?? this.reference,
    codeBarre: codeBarre.present ? codeBarre.value : this.codeBarre,
    designation: designation ?? this.designation,
    unite: unite ?? this.unite,
    prixAchatHT: prixAchatHT ?? this.prixAchatHT,
    prixVenteHT: prixVenteHT ?? this.prixVenteHT,
    tauxTVA: tauxTVA ?? this.tauxTVA,
    stockMinimum: stockMinimum ?? this.stockMinimum,
    categorieId: categorieId.present ? categorieId.value : this.categorieId,
    imageData: imageData.present ? imageData.value : this.imageData,
    actif: actif ?? this.actif,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    createdByUserId: createdByUserId.present
        ? createdByUserId.value
        : this.createdByUserId,
  );
  Produit copyWithCompanion(ProduitsCompanion data) {
    return Produit(
      id: data.id.present ? data.id.value : this.id,
      reference: data.reference.present ? data.reference.value : this.reference,
      codeBarre: data.codeBarre.present ? data.codeBarre.value : this.codeBarre,
      designation: data.designation.present
          ? data.designation.value
          : this.designation,
      unite: data.unite.present ? data.unite.value : this.unite,
      prixAchatHT: data.prixAchatHT.present
          ? data.prixAchatHT.value
          : this.prixAchatHT,
      prixVenteHT: data.prixVenteHT.present
          ? data.prixVenteHT.value
          : this.prixVenteHT,
      tauxTVA: data.tauxTVA.present ? data.tauxTVA.value : this.tauxTVA,
      stockMinimum: data.stockMinimum.present
          ? data.stockMinimum.value
          : this.stockMinimum,
      categorieId: data.categorieId.present
          ? data.categorieId.value
          : this.categorieId,
      imageData: data.imageData.present ? data.imageData.value : this.imageData,
      actif: data.actif.present ? data.actif.value : this.actif,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      createdByUserId: data.createdByUserId.present
          ? data.createdByUserId.value
          : this.createdByUserId,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Produit(')
          ..write('id: $id, ')
          ..write('reference: $reference, ')
          ..write('codeBarre: $codeBarre, ')
          ..write('designation: $designation, ')
          ..write('unite: $unite, ')
          ..write('prixAchatHT: $prixAchatHT, ')
          ..write('prixVenteHT: $prixVenteHT, ')
          ..write('tauxTVA: $tauxTVA, ')
          ..write('stockMinimum: $stockMinimum, ')
          ..write('categorieId: $categorieId, ')
          ..write('imageData: $imageData, ')
          ..write('actif: $actif, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('createdByUserId: $createdByUserId')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    reference,
    codeBarre,
    designation,
    unite,
    prixAchatHT,
    prixVenteHT,
    tauxTVA,
    stockMinimum,
    categorieId,
    $driftBlobEquality.hash(imageData),
    actif,
    createdAt,
    updatedAt,
    createdByUserId,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Produit &&
          other.id == this.id &&
          other.reference == this.reference &&
          other.codeBarre == this.codeBarre &&
          other.designation == this.designation &&
          other.unite == this.unite &&
          other.prixAchatHT == this.prixAchatHT &&
          other.prixVenteHT == this.prixVenteHT &&
          other.tauxTVA == this.tauxTVA &&
          other.stockMinimum == this.stockMinimum &&
          other.categorieId == this.categorieId &&
          $driftBlobEquality.equals(other.imageData, this.imageData) &&
          other.actif == this.actif &&
