          ..write('assignedToUserId: $assignedToUserId, ')
          ..write('date: $date, ')
          ..write('montant: $montant, ')
          ..write('mode: $mode, ')
          ..write('note: $note, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }
}

